-- Jeu de LecteurInstanceJudiciaire et EcrivainInstanceJudiciaire (« Instance judiciaire », PROC_MJUD), lot 2 du plan
-- « RIG v3 100 % fonctionnel » (plan-676a4b19). Identifiants 1 200 0xx (lot 2 : 1 200 000 a 1 299 999), roles 2026x120xx :
-- rien ne croise les instances des jeux RPJC (roles 2026F13xxx et 2026F3000x, sans code affaire, donc hors de MJUD).
-- Les tables V2 lues, aux types de RIG_DEV (INFORMATION_SCHEMA.COLUMNS de SQL-DEV\DEV, lu le 26/11/2026), seulement les
-- colonnes lues ou ecrites. v2.INSTANCE et v2.DEMANDE existent peut-etre deja (jeux joues avant, Program.cs) : elles
-- recoivent les colonnes qui leur manquent (nullables : elles ont deja des lignes), et leurs lignes passent par
-- sp_executesql -- une colonne ajoutee dans ce meme lot d'instructions n'existe pas encore quand SQL Server le compile.
-- Ce qui est retenu ou ecarte, et pourquoi : PROC_MJUD.attendu ; les gestes : PROC_MJUD.gestes ; les recherches :
-- PROC_MJUD.recherches.
IF OBJECT_ID(N'v2.INSTANCE') IS NULL
    CREATE TABLE v2.INSTANCE (INSTN_ID_INSTN int NOT NULL PRIMARY KEY, INSTN_NUM_ROLE varchar(11) NULL, INSTN_NOM_COURANT varchar(250) NULL);
IF COL_LENGTH('v2.INSTANCE', 'INSTN_CODE_AFFAIRE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_CODE_AFFAIRE varchar(10) NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_NATURE_AFFAIRE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_NATURE_AFFAIRE varchar(10) NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_CODE_ACTE_PROCE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_CODE_ACTE_PROCE varchar(3) NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_DATE_ACTE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_DATE_ACTE datetime NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_DATE_SAISINE_GREFFE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_DATE_SAISINE_GREFFE datetime NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_DATE_ENROLEMENT') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_DATE_ENROLEMENT datetime NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_DELIVRANCE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_DELIVRANCE varchar(5) NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_IP_EUROPEENNE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_IP_EUROPEENNE bit NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_NOTE_AUDIENCE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_NOTE_AUDIENCE varchar(max) NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_TYPE_INSTANCE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_TYPE_INSTANCE varchar(2) NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_TOP_EXPERIAN') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_TOP_EXPERIAN bit NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_DATE_MAJ_INFOG') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_DATE_MAJ_INFOG datetime NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_NUMERO_SOURCE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_NUMERO_SOURCE varchar(36) NULL;
IF COL_LENGTH('v2.DEMANDE', 'DMND_EN_COURS') IS NULL ALTER TABLE v2.DEMANDE ADD DMND_EN_COURS bit NULL;
IF COL_LENGTH('v2.DEMANDE', 'DMND_NOM_UTILISATEUR') IS NULL ALTER TABLE v2.DEMANDE ADD DMND_NOM_UTILISATEUR varchar(255) NULL;
IF OBJECT_ID(N'v2.CODE_AFFAIRE') IS NULL
    CREATE TABLE v2.CODE_AFFAIRE (R_CODEAFFAIR_VALEUR varchar(10) NOT NULL PRIMARY KEY, R_CODEAFFAIR_LIBELLE_ECRAN varchar(100) NOT NULL,
        R_CODEAFFAIR_TYPE_NUM_ROLE varchar(5) NULL, R_CODEAFFAIR_TYPE_INSTANCE varchar(2) NOT NULL);
IF OBJECT_ID(N'v2.NATURE_AFFAIRE') IS NULL
    CREATE TABLE v2.NATURE_AFFAIRE (R_NATUREAFFA_VALEUR varchar(10) NOT NULL PRIMARY KEY, R_NATUREAFFA_LIBELLE_ECRAN varchar(75) NULL);
IF OBJECT_ID(N'v2.CODE_ACTE_PROCE') IS NULL
    CREATE TABLE v2.CODE_ACTE_PROCE (R_CODEACTEPR_VALEUR varchar(3) NOT NULL PRIMARY KEY, R_CODEACTEPR_LIBELLE_ECRAN varchar(35) NOT NULL,
        R_CODEACTEPR_ISO varchar(20) NOT NULL);
IF OBJECT_ID(N'v2.DELIVRANCE') IS NULL
    CREATE TABLE v2.DELIVRANCE (R_DELIVRANCE_VALEUR varchar(5) NOT NULL PRIMARY KEY, R_DELIVRANCE_LIBELLE_ECRAN varchar(35) NOT NULL);
IF OBJECT_ID(N'v2.DOSSIER_DEMANDE') IS NULL
    CREATE TABLE v2.DOSSIER_DEMANDE (DSSDM_ID_DSSDM int NOT NULL PRIMARY KEY, DSSDM_ID_DMND int NOT NULL,
        DSSDM_CODE_SEQUENCEUR varchar(20) NOT NULL, DSSDM_VALEUR_SEQUENCEUR varchar(100) NULL);
IF OBJECT_ID(N'v2.ETAT_DEMANDE') IS NULL
    CREATE TABLE v2.ETAT_DEMANDE (R_ETATDEMAND_VALEUR varchar(5) NOT NULL PRIMARY KEY, R_ETATDEMAND_LIBELLE_ECRAN varchar(35) NOT NULL);
IF OBJECT_ID(N'v2.PARTIE') IS NULL
    CREATE TABLE v2.PARTIE (PRT_ID_PRT int NOT NULL PRIMARY KEY, PRT_ID_INSTN int NOT NULL, PRT_NUM_ORDRE smallint NOT NULL,
        PRT_CIVILITE varchar(7) NOT NULL, PRT_DESIGNATION varchar(512) NULL, PRT_NOM varchar(512) NULL, PRT_SIREN varchar(10) NULL,
        PRT_MODE_PRESENTATION varchar(3) NULL, PRT_QUALIF_PARTIE varchar(5) NOT NULL, PRT_DATE_ACTE datetime NULL);
IF OBJECT_ID(N'v2.AUDIENCE_CABINET') IS NULL
    CREATE TABLE v2.AUDIENCE_CABINET (AUDNC_ID_ADNC int NOT NULL PRIMARY KEY, AUDNC_DATE datetime NULL, AUDNC_HEURE varchar(5) NULL);
IF OBJECT_ID(N'v2.APPEL_AFFAIRE') IS NULL
    CREATE TABLE v2.APPEL_AFFAIRE (APPAF_ID_APPAF int NOT NULL PRIMARY KEY, APPAF_ID_INSTN int NULL, APPAF_NUM_ORDRE smallint NOT NULL,
        APPAF_ID_ADNC int NOT NULL);
IF OBJECT_ID(N'v2.TYPE_DECISION') IS NULL
    CREATE TABLE v2.TYPE_DECISION (R_TYPEDECISI_VALEUR varchar(10) NOT NULL PRIMARY KEY, R_TYPEDECISI_LIBELLE_ECRAN varchar(100) NOT NULL);
IF OBJECT_ID(N'v2.DECISION_JUDICIAIRE') IS NULL
    CREATE TABLE v2.DECISION_JUDICIAIRE (DCJDC_ID_DCJDC int NOT NULL PRIMARY KEY, DCJDC_ID_INSTN int NOT NULL, DCJDC_NUM_ORDRE smallint NOT NULL,
        DCJDC_DATE_PREVUE datetime NULL, DCJDC_DATE datetime NULL, DCJDC_TYPE_DECISION varchar(10) NULL);
IF OBJECT_ID(N'v2.CODE_EVE_PRO') IS NULL
    CREATE TABLE v2.CODE_EVE_PRO (R_CODEEVEPRO_VALEUR varchar(10) NOT NULL PRIMARY KEY, R_CODEEVEPRO_LIBELLE_ECRAN varchar(35) NOT NULL);
IF OBJECT_ID(N'v2.EVENEMENT_PROCEDURE') IS NULL
    CREATE TABLE v2.EVENEMENT_PROCEDURE (EVNPR_ID_EVNPR int NOT NULL PRIMARY KEY, EVNPR_ID_INSTN int NULL, EVNPR_NUM_ORDRE smallint NULL,
        EVNPR_CODE_EVE_PRO varchar(10) NOT NULL, EVNPR_DATE datetime NULL, EVNPR_SURVENU bit NULL, EVNPR_DELAI_EXPIRE bit NULL);

-- Les references. Types de numero de role (PROC_MJUD.Designer.cs:271) : JRCT et JROP au fond, JRREF en refere, JRIP ;
-- JRPR (prevention) est le mode MODIPR, hors de MJUD. Actes : A12 assignation (ISO 01 : la date de l'acte est celle des
-- defendeurs, non saisie), R12 requete (ISO 02 : la date de l'acte se saisit).
EXEC sp_executesql N'
INSERT INTO v2.CODE_AFFAIRE (R_CODEAFFAIR_VALEUR, R_CODEAFFAIR_LIBELLE_ECRAN, R_CODEAFFAIR_TYPE_NUM_ROLE, R_CODEAFFAIR_TYPE_INSTANCE) VALUES
    (''CT12'', ''Contentieux du banc'', ''JRCT'', ''07''), (''REF12'', ''Référé du banc'', ''JRREF'', ''09''),
    (''IP12'', ''Injonction du banc'', ''JRIP'', ''IP''), (''PR12'', ''Prévention du banc'', ''JRPR'', ''PR'');
INSERT INTO v2.NATURE_AFFAIRE (R_NATUREAFFA_VALEUR, R_NATUREAFFA_LIBELLE_ECRAN) VALUES (''N12'', ''Nature du banc'');
INSERT INTO v2.CODE_ACTE_PROCE (R_CODEACTEPR_VALEUR, R_CODEACTEPR_LIBELLE_ECRAN, R_CODEACTEPR_ISO) VALUES
    (''A12'', ''Assignation du banc'', ''01''), (''R12'', ''Requête du banc'', ''02'');
INSERT INTO v2.DELIVRANCE (R_DELIVRANCE_VALEUR, R_DELIVRANCE_LIBELLE_ECRAN) VALUES (''D12'', ''Délivrance du banc'');
IF NOT EXISTS (SELECT 1 FROM v2.ETAT_DEMANDE WHERE R_ETATDEMAND_VALEUR = ''N'')
    INSERT INTO v2.ETAT_DEMANDE (R_ETATDEMAND_VALEUR, R_ETATDEMAND_LIBELLE_ECRAN) VALUES
        (''I'', ''Interrompue''), (''N'', ''Réclamation''), (''V'', ''Validée''), (''W'', ''En attente''), (''X'', ''Supprimé'');';

-- Les instances. 1200001 au fond, requete (date de l'acte saisie) : celle que les gestes enregistrent. 1200002 en refere,
-- verrouillee par une demande EN COURS. 1200003 deja modifiee par une demande MJUD validee. 1200004 prevention (JRPR) :
-- ecartee. 1200005 une demande en attente (W) mais sur un AUTRE sequenceur (2PC) : libre. 1200006 une demande supprimee
-- (X, pas en cours) sur 2J : libre. 1200007 injonction de payer, assignation (date de l'acte des defendeurs : 01/02/2026).
-- 1200008 une demande en reclamation (N, pas en cours) sur 2J : verrouillee. Dates d'enrolement : 15/01/2026, sauf
-- 1200007 (10/02/2026).
EXEC sp_executesql N'
INSERT INTO v2.INSTANCE (INSTN_ID_INSTN, INSTN_NUM_ROLE, INSTN_NOM_COURANT, INSTN_CODE_AFFAIRE, INSTN_NATURE_AFFAIRE, INSTN_CODE_ACTE_PROCE,
    INSTN_DATE_ACTE, INSTN_DATE_SAISINE_GREFFE, INSTN_DATE_ENROLEMENT, INSTN_DELIVRANCE, INSTN_IP_EUROPEENNE, INSTN_NOTE_AUDIENCE,
    INSTN_TYPE_INSTANCE, INSTN_TOP_EXPERIAN, INSTN_DATE_MAJ_INFOG, INSTN_NUMERO_SOURCE) VALUES
    (1200001, ''2026J12001'', ''ALPHA BANC c/ BETA BANC'', ''CT12'', ''N12'', ''R12'', ''20260105'', ''20260110'', ''20260115'', ''D12'', 0, NULL, ''07'', 0, ''20200101'', NULL),
    (1200002, ''2026R12002'', ''GAMMA BANC c/ DELTA BANC'', ''REF12'', ''N12'', ''R12'', ''20260105'', ''20260110'', ''20260115'', NULL, 0, NULL, ''09'', 0, NULL, NULL),
    (1200003, ''2026J12003'', ''EPSILON BANC'', ''CT12'', ''N12'', ''R12'', ''20260105'', ''20260110'', ''20260115'', NULL, 0, NULL, ''07'', 0, NULL, NULL),
    (1200004, ''2026P12004'', ''PREVENTION BANC'', ''PR12'', ''N12'', ''R12'', ''20260105'', ''20260110'', ''20260115'', NULL, 0, NULL, ''PR'', 0, NULL, NULL),
    (1200005, ''2026J12005'', ''ETA BANC'', ''CT12'', ''N12'', ''R12'', ''20260105'', ''20260110'', ''20260115'', NULL, 0, NULL, ''07'', 0, NULL, NULL),
    (1200006, ''2026J12006'', ''ZETA BANC'', ''CT12'', ''N12'', ''R12'', ''20260105'', ''20260110'', ''20260115'', NULL, 0, NULL, ''07'', 0, NULL, NULL),
    (1200007, ''2026I12007'', ''IOTA BANC c/ KAPPA BANC'', ''IP12'', ''N12'', ''A12'', NULL, ''20260205'', ''20260210'', NULL, 0, NULL, ''IP'', 0, NULL, ''SOURCE-1200007''),
    (1200008, ''2026J12008'', ''THETA BANC'', ''CT12'', ''N12'', ''R12'', ''20260105'', ''20260110'', ''20260115'', NULL, 0, NULL, ''07'', 0, NULL, NULL);
INSERT INTO v2.DEMANDE (DMND_ID_DMND, DMND_NUM_DEMANDE, DMND_ETAT_DEMANDE, DMND_CODE_PROSS, DMND_EN_COURS, DMND_NOM_UTILISATEUR) VALUES
    (1200102, ''26012000002'', ''Q'', ''MJUD'', 1, ''M. AUTRE BANC''),
